# extracts the hex codes generated by model in extract.py
# grades against model answers

from closetllm.color import distance
from closetllm.extract import load_data
from closetllm.config import garment_hex_colors


from evals.answer_key import answer_key
#to be tweaked
THRESHOLD = 5.0

def compare_model_truth(answer_key, model_colors):
    results = []

    for garment_file_name, actual_hex in answer_key.items():
        if not actual_hex:
            continue #to be compared later bc blank rn
        if garment_file_name not in model_colors:
            print(f"{garment_file_name} is not found in clothes.json")
            continue
        model_hex = model_colors[garment_file_name][0]
        difference = distance(actual_hex, model_hex)
        results.append((garment_file_name, actual_hex, model_hex, difference))

    return results


def generate_eval_report(results):
    if not results:
        print("answer key doesnt exist")
        return
    
    passed = [row for row in results if row[3] < THRESHOLD]
    average = sum(row[3] for row in results) / len(results)
    worst = max(results, key=lambda row: row[3])
 
    print(f"\nmeasured:    {len(results)} garments")
    print(f"pass rate:   {len(passed)}/{len(results)}  (gap < {THRESHOLD})")
    print(f"average gap: {average:.1f}")
    print(f"worst miss:  {worst[0]}  "
          f"(measured {worst[1]}, model said {worst[2]}, gap {worst[3]:.1f})")

    print("\nall garments (sorted by gap):")
    for garment_file_name, actual_hex, model_hex, difference in sorted(
        results, key=lambda row: row[3], reverse=True
    ):
        status = "PASS" if difference < THRESHOLD else "FAIL"
        print(f"  [{status}] {garment_file_name}  "
              f"measured {actual_hex}, model said {model_hex}, gap {difference:.1f}")

    
if __name__ == "__main__":
    model_colors = load_data(garment_hex_colors)   # the model's guesses
    results = compare_model_truth(answer_key, model_colors)
    generate_eval_report(results)
 